package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Resolves the effective registration date for a create request and publishes it as a
 * variable. The effective date is the one supplied in the request, or the server's current
 * date when omitted; either way, a weekend is rolled forward to the next business day (see
 * {@link BusinessDays}). Runs before {@link EnsureDailyLimit} and {@link ApplyRegistrationDate}
 * so the per-day limit counts against, and the built owner is stamped with, the same adjusted
 * business day — and so everything derived from it (e.g. the membership-number year segment)
 * uses the adjusted date.
 */
public class ResolveRegistrationDate {

    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
        LocalDate supplied = request.getRegistrationDate();
        LocalDate effective = supplied != null ? supplied : LocalDate.now();
        registrationDate.set(BusinessDays.rollForward(effective));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Stamps a newly built owner with the effective registration date resolved by
 * {@link ResolveRegistrationDate}. Runs after {@link BuildOwner} and mutates the built
 * owner in place, overwriting whatever date the request body mapped in, so the owner is
 * stored and returned with the adjusted business day and later steps (e.g.
 * {@link AssignMembershipNumber}) derive their values from it.
 */
public class ApplyRegistrationDate {

    public void service(@Val Owner owner, @Val LocalDate registrationDate) {
        owner.setRegistrationDate(registrationDate);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        dto.setBulkSignupWarning(BulkSignup.warningRaised(ownerRepository));
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

/**
 * Validates the optional owner {@code registrationDate}. The date is optional, so a null
 * value is left untouched; when supplied it must not be later than the server's current
 * date (otherwise a 400 via {@link FutureRegistrationDateException}). Runs before
 * {@link ResolveRegistrationDate} so a future date is rejected before it is rolled forward
 * to a business day or counted against the daily limit.
 */
public class ValidateRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied == null) {
            return;
        }
        LocalDate serverDate = LocalDate.now();
        if (supplied.isAfter(serverDate)) {
            throw new FutureRegistrationDateException(supplied, serverDate);
        }
    }
}

